int
mask,
int
&events[])
  {
   ArrayResize(events,0);
int
n=0;
for
(
int
e=0;e<16;e++)
     {
if
((mask & EventBit(e)) != 0)
         {
           ArrayResize(events,n+1);
           events[n]=e;
           n++;
       }
     }
return
(n);
